// ai-agents/slack-app/src/app.ts (part 1, from G3-30). Socket Mode: no public webhook.
import { App } from "@slack/bolt";

const app = new App({ token: process.env.SLACK_BOT_TOKEN, appToken: process.env.SLACK_APP_TOKEN, socketMode: true });
const USAGE = "Try /nova RH-1234, /nova status RH-1234 or /nova stop RH-1234.";

app.command("/nova", async ({ ack, command, respond }) => {
  await ack(); // Slack needs an answer within 3 seconds; the work happens after
  const words = command.text.trim().split(/\s+/).filter(Boolean);
  const [verb, key] = words.length > 1 ? [words[0], words[1]!.toUpperCase()] : ["start", (words[0] ?? "").toUpperCase()];
  if (!JIRA_KEY.test(key)) {
    await respond(USAGE);
    return;
  }
  // part 2: the verbs
});

await app.start(); // dials out to Slack over a WebSocket

// ai-agents/slack-app/src/app.ts (part 2): inside the /nova handler
const by = people.bySlackId(command.user_id); // config/people.yaml (G4-05)
const temporal = await temporalClient();
const handle = temporal.workflow.getHandle(`nova:${key}`);
if (verb === "start") {
  // G4-05 turns this into "assign the ticket to Nova", so the poll starts it and records the requester
  await startRun(temporal, "nova", key, "ticketToPr", { key, requester: by.jiraAccountId });
  await respond(`Nova has ${key}. Follow along in its thread.`);
} else if (verb === "status") {
  await respond(oneLine(await handle.query<RunStatus>("status")));
} else if (verb === "stop") {
  await handle.signal("stop", by);
  await respond(`Stopping ${key}. The branch and notes are kept.`);
} else {
  await respond(USAGE);
}

// ai-agents/slack-app/src/status.ts (sketch): one thread per ticket; its first message is edited in place
import type { WebClient } from "@slack/web-api";

export const openThread = async (client: WebClient, key: string) => {
  const res = await client.chat.postMessage({ channel: NOVA_CHANNEL, text: `${key} · Nova: Checking` });
  return { channel: res.channel!, ts: res.ts! }; // becomes the run's Slack scope in the broker
};

export const setStatus = async (client: WebClient, t: Thread, key: string, state: NovaState, doing: string) => {
  await client.chat.update({ channel: t.channel, ts: t.ts, text: `${key} · Nova: ${state}. ${doing}` });
};

export const reply = async (client: WebClient, t: Thread, text: string) => {
  await client.chat.postMessage({ channel: t.channel, thread_ts: t.ts, text }); // inside the thread
};

// ai-agents/slack-app/src/actions.ts (part of G3-35). G4-14 owns the plan's look and who may decide.
const SIGNALS: Record<string, string> = { plan_approve: "decidePlan", plan_stop: "stop", run_stop: "stop", backstop_continue: "resume" };

app.action(/^(plan_approve|plan_change|plan_stop|run_stop|backstop_continue)$/, async ({ ack, body, action, client }) => {
  await ack();
  if (body.type !== "block_actions" || action.type !== "button") return;
  const [workflowId = "", version = ""] = (action.value ?? "").split("|"); // "nova:RH-1234|v2": plan v2 (G4-14)
  const person = people.bySlackId(body.user.id);
  if (!(await mayDecide(person, workflowId, action.action_id))) { // G4-14: only the requester
    return ephemeral(client, body, "Only the requester can decide this.");
  }
  if (action.action_id === "plan_change") {
    await client.views.open({ trigger_id: body.trigger_id, view: changeModal(workflowId, version) });
    return;
  }
  const payload = action.action_id === "plan_approve" ? { kind: "approve", by: person.email, version } : person.email;
  try {
    await (await temporalClient()).workflow.getHandle(workflowId).signal(SIGNALS[action.action_id]!, payload);
  } catch { // Temporal down: never drop a decision silently
    return ephemeral(client, body, "That didn't reach Nova. Please try again in a minute.");
  }
  await client.chat.update({ channel: body.channel?.id ?? "", ts: body.message?.ts ?? "", // no second click
    blocks: decidedBlocks(body.message, action.action_id, person) });
});

// ai-agents/slack-app/src/actions.ts (end of G3-35): a person's reply in a ticket's thread is an answer
app.event("message", async ({ event }) => {
  if (event.subtype !== undefined || event.bot_id || !event.thread_ts) return; // only people, only inside a thread
  const workflowId = await workflowForThread(event.channel, event.thread_ts); // the broker knows which run posted there
  if (!workflowId) return;
  const person = people.bySlackId(event.user);
  await (await temporalClient()).workflow.getHandle(workflowId).signal("answerQuestion", event.text ?? "", person.email);
});

