import { App } from "@slack/bolt";
import { Client, Connection } from "@temporalio/client";

const app = new App({ token: process.env.SLACK_BOT_TOKEN, appToken: process.env.SLACK_APP_TOKEN, socketMode: true });
const temporal = new Client({ connection: await Connection.connect({ address: "localhost:7233" }), namespace: "ai-agents" });

app.command("/nova-lab", async ({ ack, command, respond, client }) => {
  await ack(); // within 3 seconds; the work comes after
  const key = command.text.trim().toUpperCase();
  if (!/^[A-Z]+-\d+$/.test(key)) return void (await respond("Try /nova-lab RH-1"));
  const workflowId = `lab:${key}`;
  await temporal.workflow.start("hello", { taskQueue: "ai-agents-lab", workflowId, args: [key],
    workflowIdConflictPolicy: "USE_EXISTING" });
  await client.chat.postMessage({ channel: command.channel_id, text: `${key}: waiting for approval`,
    blocks: [
      { type: "section", text: { type: "mrkdwn", text: `*${key}*: waiting for approval` } },
      { type: "actions", elements: [{ type: "button", action_id: "lab_approve", style: "primary",
        value: workflowId, text: { type: "plain_text", text: "Approve" } }] },
    ] });
});

app.action("lab_approve", async ({ ack, body, action, client }) => {
  await ack();
  if (body.type !== "block_actions" || action.type !== "button") return;
  await temporal.workflow.getHandle(action.value ?? "").signal("approve", body.user.id);
  await client.chat.update({ channel: body.channel?.id ?? "", ts: body.message?.ts ?? "",
    text: `${action.value}: approved by <@${body.user.id}>`, blocks: [] }); // no buttons: no second click
});

await app.start();
console.log("nova-lab is running in Socket Mode");
